// @FIGURE_CODE_BEGIN
const W = 700, H = 500;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

const COLORS = {
  ray: '#1381A2',
  barrier: '#C49A6C',
  screen: '#A0A0A0',
  dim: '#444444',
  text: '#000000',
  wave: '#1381A2'
};

let state = {
  y: 2.5,
  d: 1,
  mode: 0 // 0 = Full apparatus, 1 = Near-slit approximation
};

const steps = [
  {
    title: "Full apparatus",
    narration: "Light from two slits travels along paths r1 and r2 to meet at point P. The angle θ describes the direction to P relative to the center line.",
    state: { mode: 0, y: 2.5, d: 1 }
  },
  {
    title: "Change observation angle",
    narration: "Dragging P higher on the screen increases θ and makes the lower path r2 significantly longer than the upper path r1.",
    state: { mode: 0, y: 4.5, d: 1 }
  },
  {
    title: "Parallel ray approximation",
    narration: "Zooming in near the slits, we see that the immense distance to the screen means the rays are effectively parallel. A perpendicular dropped from S1 isolates the path difference Δl.",
    state: { mode: 1, y: 4.5, d: 1 }
  },
  {
    title: "Varying slit separation",
    narration: "With the parallel geometry visible, widening the slits clearly lengthens the Δl segment. The path difference depends on both d and θ (Δl = d sin θ).",
    state: { mode: 1, y: 4.5, d: 2 }
  }
];

let currentStep = 0;

window.update_yPosition = function(v) { state.y = v; drawScene(); };
window.update_slitSeparation = function(v) { state.d = v; drawScene(); };
window.update_viewMode = function(v) { state.mode = (v === "Near-slit approximation") ? 1 : 0; drawScene(); };

function applyState(s) {
  state.y = s.y;
  state.d = s.d;
  state.mode = s.mode;

  document.getElementById('yPositionInput').value = s.y;
  document.getElementById('yPositionVal').value = s.y;
  document.getElementById('slitSeparationInput').value = s.d;
  document.getElementById('slitSeparationVal').value = s.d;
  document.getElementById('viewModeInput').value = s.mode === 1 ? "Near-slit approximation" : "Full apparatus";

  drawScene();
}

window.updateStepUI = function() {
  document.getElementById('stepLabel').innerText = `${currentStep + 1}. ${steps[currentStep].title}`;
  document.getElementById('demoNarration').innerText = steps[currentStep].narration;
  document.getElementById('btnPrev').disabled = currentStep === 0;
  document.getElementById('btnNext').disabled = currentStep === steps.length - 1;
};

window.nextStep = function() {
  if (currentStep < steps.length - 1) {
    currentStep++;
    applyState(steps[currentStep].state);
    updateStepUI();
  }
};

window.prevStep = function() {
  if (currentStep > 0) {
    currentStep--;
    applyState(steps[currentStep].state);
    updateStepUI();
  }
};

// ─── DRAWING HELPERS ────────────────────────────────────────────────────────────

function createRayMarker(parent) {
  return parent.marker(12, 12, function(add) {
    add.path('M0,2 L10,6 L0,10 L3,6 z').fill(COLORS.ray);
  }).ref(9, 6).orient('auto');
}

function drawDimension(parent, x1, y1, x2, y2, labelText, offset) {
  let arrowStart = parent.marker(10, 10, function(add) {
    add.path('M10,2 L0,5 L10,8 z').fill(COLORS.dim);
  }).ref(0, 5).orient('auto');

  let arrowEnd = parent.marker(10, 10, function(add) {
    add.path('M0,2 L10,5 L0,8 z').fill(COLORS.dim);
  }).ref(10, 5).orient('auto');

  let dx = x2 - x1, dy = y2 - y1;
  let len = Math.sqrt(dx*dx + dy*dy);
  if (len < 1e-3) return;

  let nx = -dy/len, ny = dx/len;
  let ox1 = x1 + nx * offset, oy1 = y1 + ny * offset;
  let ox2 = x2 + nx * offset, oy2 = y2 + ny * offset;

  parent.line(ox1, oy1, ox2, oy2).stroke({width: 1, color: COLORS.dim})
        .marker('start', arrowStart).marker('end', arrowEnd);

  let cx = (ox1 + ox2)/2, cy = (oy1 + oy2)/2;
  let tx = cx + nx * (offset >= 0 ? 15 : -15);
  let ty = cy + ny * (offset >= 0 ? 15 : -15);

  parent.text(labelText).move(tx - 6, ty - 10).font({size: 14, style: 'italic'})
        .attr({'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round'});
}

function drawAngleArc(parent, cx, cy, startAngle, endAngle, radius, label) {
  let x1 = cx + radius * Math.cos(startAngle);
  let y1 = cy + radius * Math.sin(startAngle);
  let x2 = cx + radius * Math.cos(endAngle);
  let y2 = cy + radius * Math.sin(endAngle);

  let diff = endAngle - startAngle;
  while (diff > Math.PI) diff -= 2*Math.PI;
  while (diff < -Math.PI) diff += 2*Math.PI;

  let sweepFlag = diff > 0 ? 1 : 0;
  let largeArcFlag = Math.abs(diff) > Math.PI ? 1 : 0;

  parent.path(`M ${x1} ${y1} A ${radius} ${radius} 0 ${largeArcFlag} ${sweepFlag} ${x2} ${y2}`)
        .fill('none').stroke({width: 1.2, color: '#333'});

  let midAngle = startAngle + diff / 2;
  let tx = cx + (radius + 14) * Math.cos(midAngle);
  let ty = cy + (radius + 14) * Math.sin(midAngle);

  parent.text(label).move(tx - 5, ty - 10).font({size: 14, style: 'italic'})
        .attr({'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4});
}

function drawWave(parent, x1, y1, x2, y2) {
  let dx = x2 - x1, dy = y2 - y1;
  let len = Math.sqrt(dx*dx + dy*dy);
  if (len < 1e-3) return;

  let nx = -dy/len, ny = dx/len;
  let waveAmp = 10, waveLen = 40;
  let drawLen = Math.min(3 * waveLen, len);
  let steps = 100, pts = [];

  for (let i = 0; i <= steps; i++) {
    let t = (i / steps) * drawLen;
    let disp = Math.sin((t / waveLen) * Math.PI * 2) * waveAmp;
    pts.push(`${x1 + (dx/len) * t + nx * disp},${y1 + (dy/len) * t + ny * disp}`);
  }
  parent.polyline(pts.join(' ')).fill('none').stroke({width: 1.5, color: COLORS.wave});
}

function drawBarrier(parent, x, y_center, d_px, mode) {
  let y_s1 = y_center - d_px;
  let y_s2 = y_center + d_px;
  let gap = mode === 0 ? 10 : 20;

  parent.line(x, 0, x, y_s1 - gap/2).stroke({width: 4, color: COLORS.barrier});
  parent.line(x, y_s1 + gap/2, x, y_s2 - gap/2).stroke({width: 4, color: COLORS.barrier});
  parent.line(x, y_s2 + gap/2, x, H).stroke({width: 4, color: COLORS.barrier});

  parent.text('S₁').move(x - 26, y_s1 - 12).font({size: 15});
  parent.text('S₂').move(x - 26, y_s2 - 12).font({size: 15});
}

// ─── MAIN SCENES ────────────────────────────────────────────────────────────────

function drawFullApparatus() {
  let X_barrier = 150, X_screen = 550, Y_center = 250;
  let D_px = X_screen - X_barrier;
  let d_px = state.d * 20;
  let Y_S1 = Y_center - d_px;
  let Y_S2 = Y_center + d_px;
  let Y_P = Y_center - state.y * 30;

  // Screen
  let screenLine = draw.line(X_screen, 40, X_screen, 440).stroke({width: 4, color: COLORS.screen});
  draw.text('Screen').move(X_screen - 20, 15).font({size: 14});
  screenLine.css('cursor', 'pointer').on('click', () => showPopup('Interference Screen', 'The converging rays interfere here. A bright or dark spot forms depending on the path difference Δl.'));

  drawBarrier(draw, X_barrier, Y_center, d_px, 0);

  // Points
  draw.circle(6).center(X_screen, Y_P).fill('#000');
  draw.text('P').move(X_screen + 10, Y_P - 12).font({size: 16, style: 'italic'});
  draw.text('C').move(X_screen + 10, Y_center - 12).font({size: 15, style: 'italic'});

  // Dashed framework
  draw.line(X_barrier, Y_center, X_screen, Y_center).stroke({width: 1, color: '#666', dasharray: '6,4'});
  draw.line(X_barrier, Y_center, X_screen, Y_P).stroke({width: 1, color: '#666', dasharray: '6,4'});

  // Rays
  let rayMarker = createRayMarker(draw);
  draw.line(X_barrier, Y_S1, X_screen, Y_P).stroke({width: 1.5, color: COLORS.ray}).marker('end', rayMarker);
  draw.line(X_barrier, Y_S2, X_screen, Y_P).stroke({width: 1.5, color: COLORS.ray}).marker('end', rayMarker);

  // Waves
  drawWave(draw, X_barrier, Y_S1, X_screen, Y_P);
  drawWave(draw, X_barrier, Y_S2, X_screen, Y_P);

  // Labels r1, r2
  let r1_cx = X_barrier + (X_screen - X_barrier) * 0.45;
  let r1_cy = Y_S1 + (Y_P - Y_S1) * 0.45;
  draw.text('r₁').move(r1_cx - 15, r1_cy - 25).font({size: 15, style: 'italic'}).attr({'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4});

  let r2_cx = X_barrier + (X_screen - X_barrier) * 0.6;
  let r2_cy = Y_S2 + (Y_P - Y_S2) * 0.6;
  draw.text('r₂').move(r2_cx + 5, r2_cy + 5).font({size: 15, style: 'italic'}).attr({'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4});

  // Dimensions
  drawDimension(draw, X_barrier, 410, X_screen, 410, 'D', 0);
  draw.line(X_barrier, 280, X_barrier, 420).stroke({width: 1, color: '#999', dasharray: '2,2'});
  draw.line(X_screen, Y_center + 10, X_screen, 420).stroke({width: 1, color: '#999', dasharray: '2,2'});

  drawDimension(draw, X_barrier, Y_S1, X_barrier, Y_S2, 'd', 50);

  drawDimension(draw, X_screen, Y_center, X_screen, Y_P, 'y', 40);
  draw.line(X_screen, Y_P, X_screen + 50, Y_P).stroke({width: 1, color: '#999', dasharray: '2,2'});
  draw.line(X_screen, Y_center, X_screen + 50, Y_center).stroke({width: 1, color: '#999', dasharray: '2,2'});

  let angle = Math.atan2(Y_P - Y_center, D_px);
  if (Math.abs(angle) > 0.02) {
    drawAngleArc(draw, X_barrier, Y_center, 0, angle, 60, 'θ');
  }

  draw.text('(a)').move(W/2, 460).font({size: 16, family: 'sans-serif'}).center(W/2, 470);
}

function drawNearSlitApparatus() {
  let X_barrier = 200, Y_center = 250;
  let d_px = state.d * 60;
  let Y_S1 = Y_center - d_px;
  let Y_S2 = Y_center + d_px;

  let D_px_virtual = 400;
  let Y_P_virtual = Y_center - state.y * 30;
  let theta = Math.atan2(Y_P_virtual - Y_center, D_px_virtual);

  let rx = Math.cos(theta), ry = Math.sin(theta);
  let rayLen = 400;
  let S1_end = { x: X_barrier + rayLen * rx, y: Y_S1 + rayLen * ry };
  let S2_end = { x: X_barrier + rayLen * rx, y: Y_S2 + rayLen * ry };

  let dot = (Y_S1 - Y_S2) * ry; // Projection distance
  let Q = { x: X_barrier + dot * rx, y: Y_S2 + dot * ry };

  drawBarrier(draw, X_barrier, Y_center, d_px, 1);

  // Rays
  let rayMarker = createRayMarker(draw);
  draw.line(X_barrier, Y_S1, S1_end.x, S1_end.y).stroke({width: 2, color: COLORS.ray}).marker('end', rayMarker);
  draw.line(X_barrier, Y_S2, S2_end.x, S2_end.y).stroke({width: 2, color: COLORS.ray}).marker('end', rayMarker);

  draw.text('to P').move(S1_end.x + 5, S1_end.y - 10).font({size: 15, style: 'italic'});
  draw.text('to P').move(S2_end.x + 5, S2_end.y - 10).font({size: 15, style: 'italic'});

  // Horizontal guidelines & theta angles
  draw.line(X_barrier, Y_S1, X_barrier + 150, Y_S1).stroke({width: 1, color: '#666', dasharray: '6,4'});
  draw.line(X_barrier, Y_S2, X_barrier + 220, Y_S2).stroke({width: 1, color: '#666', dasharray: '6,4'});

  if (Math.abs(theta) > 0.02) {
    drawAngleArc(draw, X_barrier, Y_S1, 0, theta, 60, 'θ');
    drawAngleArc(draw, X_barrier, Y_S2, 0, theta, 60, 'θ');
  }

  // Perpendicular line
  draw.line(X_barrier, Y_S1, Q.x, Q.y).stroke({width: 1.5, color: '#000', dasharray: '5,3'});

  // Right angle symbol at Q
  let qx = X_barrier - Q.x, qy = Y_S1 - Q.y;
  let qlen = Math.sqrt(qx*qx + qy*qy);
  if (qlen > 2) {
    qx /= qlen; qy /= qlen;
    let s = 12;
    let c1x = Q.x - rx * s, c1y = Q.y - ry * s;
    let c3x = Q.x + qx * s, c3y = Q.y + qy * s;
    let c2x = c1x + qx * s, c2y = c1y + qy * s;
    draw.polyline(`${c1x},${c1y} ${c2x},${c2y} ${c3x},${c3y}`).fill('none').stroke({width: 1, color: '#000'});
  }

  // Inner triangle theta at S1
  if (Math.abs(theta) > 0.02) {
    let angleS1Q = Math.atan2(Q.y - Y_S1, Q.x - X_barrier);
    let ar = 45;
    let ax1 = X_barrier + ar * Math.cos(angleS1Q);
    let ay1 = Y_S1 + ar * Math.sin(angleS1Q);
    let ax2 = X_barrier; // Vertical down (PI/2)
    let ay2 = Y_S1 + ar;

    let sweep = (Math.PI/2 - angleS1Q > 0) ? 1 : 0;
    draw.path(`M ${ax1} ${ay1} A ${ar} ${ar} 0 0 ${sweep} ${ax2} ${ay2}`).fill('none').stroke({width: 1, color: '#333'});

    let mAngle = (angleS1Q + Math.PI/2) / 2;
    draw.text('θ').move(X_barrier + (ar+14)*Math.cos(mAngle) - 6, Y_S1 + (ar+14)*Math.sin(mAngle) - 10)
        .font({size: 14, style: 'italic'}).attr({'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4});
  }

  drawDimension(draw, X_barrier, Y_S1, X_barrier, Y_S2, 'd', 60);

  // Δl dimension
  let nx = -ry, ny = rx; // Normal pointing down-right relative to ray
  let offDist = 35;
  let ox1 = X_barrier + nx * offDist, oy1 = Y_S2 + ny * offDist;
  let ox2 = Q.x + nx * offDist, oy2 = Q.y + ny * offDist;

  draw.line(X_barrier, Y_S2, ox1 + nx*4, oy1 + ny*4).stroke({width: 1, color: '#999', dasharray: '2,2'});
  draw.line(Q.x, Q.y, ox2 + nx*4, oy2 + ny*4).stroke({width: 1, color: '#999', dasharray: '2,2'});

  if (dot > 2) {
    let dimArrowStart = draw.marker(10, 10, function(add) { add.path('M10,2 L0,5 L10,8 z').fill(COLORS.dim); }).ref(0, 5).orient('auto');
    let dimArrowEnd = draw.marker(10, 10, function(add) { add.path('M0,2 L10,5 L0,8 z').fill(COLORS.dim); }).ref(10, 5).orient('auto');

    draw.line(ox1, oy1, ox2, oy2).stroke({width: 1, color: COLORS.dim})
        .marker('start', dimArrowStart).marker('end', dimArrowEnd);

    let mx = (ox1 + ox2)/2 + nx * 14;
    let my = (oy1 + oy2)/2 + ny * 14;
    draw.text('Δl').move(mx - 8, my - 12).font({size: 15, style: 'italic'})
        .attr({'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4});
  }

  draw.text('(b)').move(W/2, 460).font({size: 16, family: 'sans-serif'}).center(W/2, 470);
}

function drawScene() {
  draw.clear();
  if (state.mode === 0) {
    drawFullApparatus();
  } else {
    drawNearSlitApparatus();
  }
}

